"""Web Companion HTML and Static Assets for Zero-Setup Judge Testing."""
COMPANION_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>Volcan — Accessible Voice & Braille AI Agent Forge</title>\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;600;800&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">\n  <style>\n    :root {\n      --bg: #070a12;\n      --surface: #0f172a;\n      --surface-border: #1e293b;\n      --primary: #f97316;\n      --primary-glow: rgba(249, 115, 22, 0.35);\n      --secondary: #38bdf8;\n      --secondary-glow: rgba(56, 189, 248, 0.3);\n      --accent-green: #22c55e;\n      --accent-red: #ef4444;\n      --text: #f8fafc;\n      --text-muted: #94a3b8;\n    }\n    * { box-sizing: border-box; margin: 0; padding: 0; font-family: \'Plus Jakarta Sans\', sans-serif; }\n    body { background: var(--bg); color: var(--text); padding: 30px 20px; line-height: 1.6; min-height: 100vh; }\n    .container { max-width: 1200px; margin: 0 auto; }\n    \n    header {\n      display: flex; justify-content: space-between; align-items: center;\n      padding-bottom: 24px; border-bottom: 1px solid var(--surface-border); margin-bottom: 30px;\n      flex-wrap: wrap; gap: 16px;\n    }\n    .brand h1 { font-size: 2rem; font-weight: 800; color: #fff; display: flex; align-items: center; gap: 12px; }\n    .brand h1 span { color: var(--primary); text-shadow: 0 0 20px var(--primary-glow); }\n    .brand p { color: var(--text-muted); font-size: 0.95rem; margin-top: 4px; }\n    .badges-row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }\n    .badge {\n      background: rgba(56, 189, 248, 0.1); border: 1px solid rgba(56, 189, 248, 0.3);\n      color: var(--secondary); padding: 6px 14px; border-radius: 999px; font-size: 0.8rem; font-weight: 600;\n      box-shadow: 0 0 10px rgba(56, 189, 248, 0.15);\n    }\n    .badge-orange {\n      background: rgba(249, 115, 22, 0.15); border-color: rgba(249, 115, 22, 0.4); color: #fdba74;\n    }\n    .badge-braille {\n      background: rgba(168, 85, 247, 0.15); border-color: rgba(168, 85, 247, 0.4); color: #d8b4fe;\n    }\n    \n    .voice-bar {\n      background: linear-gradient(90deg, #1e1b4b 0%, #0f172a 100%);\n      border: 1px solid #4338ca; border-radius: 12px; padding: 14px 20px;\n      margin-bottom: 24px; display: flex; align-items: center; gap: 16px;\n      box-shadow: 0 4px 20px rgba(67, 56, 202, 0.25);\n    }\n    .voice-icon { font-size: 1.5rem; animation: pulse 2s infinite; }\n    @keyframes pulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.15); } }\n    .voice-input-wrap { flex: 1; display: flex; gap: 10px; }\n    .voice-input {\n      flex: 1; background: #070a13; border: 1px solid #334155; border-radius: 8px;\n      padding: 10px 14px; color: #fff; font-size: 0.9rem;\n    }\n    .voice-input:focus { outline: none; border-color: var(--secondary); }\n\n    .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }\n    @media (max-width: 860px) { .grid { grid-template-columns: 1fr; } }\n    @media (max-width: 480px) {\n      body { padding: 12px 8px; }\n      header { flex-direction: column; align-items: flex-start; gap: 10px; }\n      .brand h1 { font-size: 1.4rem; }\n      .voice-bar { flex-direction: column; align-items: stretch; padding: 12px; gap: 10px; }\n      .voice-input-wrap { flex-direction: column; }\n      button { width: 100%; justify-content: center; }\n      .actions-bar { flex-direction: column; }\n    }\n    .empty-state-card {\n      background: rgba(15, 23, 42, 0.6); border: 1px dashed #334155; border-radius: 6px;\n      padding: 14px; color: var(--text-muted); font-size: 0.85rem; text-align: center;\n    }\n    \n    .card {\n      background: var(--surface); border: 1px solid var(--surface-border);\n      border-radius: 14px; padding: 24px; position: relative; overflow: hidden;\n      box-shadow: 0 10px 30px rgba(0,0,0,0.5);\n    }\n    .card h2 { font-size: 1.25rem; font-weight: 700; margin-bottom: 8px; color: #fff; display: flex; align-items: center; gap: 10px; }\n    .card-desc { color: var(--text-muted); font-size: 0.88rem; margin-bottom: 18px; }\n\n    .preset-chips { display: flex; gap: 8px; margin-bottom: 12px; flex-wrap: wrap; }\n    .chip {\n      background: #1e293b; border: 1px solid #334155; color: var(--text-muted);\n      padding: 4px 10px; border-radius: 6px; font-size: 0.75rem; cursor: pointer; transition: all 0.2s;\n    }\n    .chip:hover, .chip.active { background: var(--primary); color: #fff; border-color: var(--primary); }\n\n    textarea {\n      width: 100%; height: 140px; background: #070a13; border: 1px solid var(--surface-border);\n      color: #38bdf8; padding: 14px; border-radius: 8px; font-family: \'JetBrains Mono\', monospace;\n      font-size: 0.82rem; resize: vertical; line-height: 1.4;\n    }\n    textarea:focus { outline: none; border-color: var(--primary); }\n\n    .actions-bar { display: flex; gap: 10px; margin-top: 14px; flex-wrap: wrap; }\n    button {\n      background: var(--primary); color: white; border: none; padding: 10px 18px;\n      border-radius: 8px; cursor: pointer; font-weight: 600; font-size: 0.88rem;\n      transition: all 0.2s; display: inline-flex; align-items: center; gap: 8px;\n    }\n    button:hover { background: #ea580c; transform: translateY(-1px); box-shadow: 0 4px 15px var(--primary-glow); }\n    .btn-secondary { background: #1e293b; border: 1px solid #334155; color: var(--text); }\n    .btn-secondary:hover { background: #334155; }\n    .btn-purple { background: #7e22ce; color: #fff; }\n    .btn-purple:hover { background: #6b21a8; }\n    .btn-danger { background: #dc2626; }\n    .btn-danger:hover { background: #b91c1c; }\n\n    .console-box {\n      background: #070a13; border: 1px solid var(--surface-border); border-radius: 8px;\n      padding: 16px; margin-top: 16px; min-height: 140px; font-size: 0.9rem;\n    }\n    .console-header {\n      font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.05em;\n      color: var(--text-muted); margin-bottom: 10px; display: flex; justify-content: space-between;\n    }\n    .tag { display: inline-block; padding: 2px 8px; border-radius: 4px; font-size: 0.75rem; font-weight: 700; }\n    .tag-sec { background: rgba(239, 68, 68, 0.2); border: 1px solid #ef4444; color: #fca5a5; }\n    .tag-succ { background: rgba(34, 197, 94, 0.2); border: 1px solid #22c55e; color: #86efac; }\n    .tag-lease { background: rgba(249, 115, 22, 0.2); border: 1px solid var(--primary); color: #fed7aa; }\n    .tag-braille { background: rgba(168, 85, 247, 0.2); border: 1px solid #a855f7; color: #e9d5ff; }\n\n    .braille-stream {\n      font-family: \'JetBrains Mono\', monospace; font-size: 1.3rem; letter-spacing: 3px; line-height: 1.8;\n      color: #c084fc; background: #030712; padding: 16px; border-radius: 8px; border: 1px solid #581c87;\n      max-height: 160px; overflow-y: auto; white-space: pre-wrap; word-break: break-all;\n    }\n\n    canvas#audioVisualizer {\n      width: 100%; height: 55px; background: #070a13; border: 1px solid var(--surface-border);\n      border-radius: 6px; margin-top: 12px; display: block;\n    }\n\n    .audit-list {\n      font-family: \'JetBrains Mono\', monospace; font-size: 0.78rem; color: var(--text-muted);\n      max-height: 160px; overflow-y: auto; display: flex; flex-direction: column; gap: 6px;\n    }\n    .audit-item { padding: 5px 10px; background: #070a13; border-radius: 4px; border-left: 3px solid var(--secondary); }\n  </style>\n</head>\n<body>\n  <div class="container">\n    <header>\n      <div class="brand">\n        <h1>🌋 <span>Volcan</span> Voice & Braille Agent Forge</h1>\n        <p>Accessible Multi-Modal AI Infrastructure on Amazon Alexa+, AWS Bedrock & Braille Terminals</p>\n      </div>\n      <div class="badges-row">\n        <span class="badge badge-orange">Alexa+ Voice First</span>\n        <span class="badge badge-braille">⠠⠃⠗⠁⠊⠇⠇⠑ Braille (U+2800)</span>\n        <span class="badge">Model Context Protocol</span>\n        <span class="badge">Pure PCM Audio 22kHz</span>\n      </div>\n    </header>\n\n    <!-- Alexa Voice Query Simulator Bar -->\n    <div class="voice-bar">\n      <div class="voice-icon">🎙️</div>\n      <div class="voice-input-wrap">\n        <input type="text" id="voiceCommandInput" class="voice-input" value="Alexa, summarize my workspace diff" placeholder="Speak or type an Alexa command..." aria-label="Alexa voice command simulation">\n        <button data-testid="primary-hero-action" class="primary-action" title="Click or tap to synthesize voice digest and audio earcon" onclick="executeVoiceCommand()">🎙️ Speak Alexa Query</button>\n      </div>\n      <div class="preset-chips" style="margin-bottom:0;">\n        <span class="chip" onclick="setVoicePrompt(\'Alexa, summarize my workspace diff\')">Diff Summary</span>\n        <span class="chip" onclick="setVoicePrompt(\'Alexa, stage deploy to production\')">Stage Deploy</span>\n        <span class="chip" onclick="setVoicePrompt(\'Alexa, approve action with token\')">Approve Lease</span>\n      </div>\n    </div>\n\n    <div class="grid">\n      <!-- Card 1: Semantic Diff Sonification -->\n      <div class="card">\n        <h2>🎧 AST Diff & Spatial Audio Sonification</h2>\n        <p class="card-desc">\n          Volcan parses AST changes and replaces dense terminal diffs with hierarchical voice digests, synthesized speech, and acoustic earcons.\n        </p>\n\n        <div class="preset-chips">\n          <span class="chip active" onclick="loadPreset(1)">Security Flag (KMS Key)</span>\n          <span class="chip" onclick="loadPreset(2)">Clean Refactor (FastAPI)</span>\n          <span class="chip" onclick="loadPreset(3)">Bugfix (Null Check)</span>\n        </div>\n\n        <textarea id="diffInput"></textarea>\n\n        <div class="actions-bar">\n          <button onclick="synthesizeDiff(0)">🔊 Synthesize Executive (Level 0)</button>\n          <button class="btn-secondary" onclick="synthesizeDiff(1)">Level 1 (Detailed)</button>\n          <button class="btn-secondary" onclick="playPureEarcon(\'DIFF_READY\')">Play Earcon</button>\n        </div>\n\n        <canvas id="audioVisualizer"></canvas>\n\n        <div class="console-box" id="diffConsole">\n          <div class="console-header">\n            <span>Voice Digest & AST Inspection</span>\n            <span id="astLatency">0.056 ms</span>\n          </div>\n          <div id="diffOutput">Ready. Click synthesize to parse AST, play harmonic earcon, and speak voice summary.</div>\n        </div>\n      </div>\n\n      <!-- Card 2: Dual-Custody Governance -->\n      <div class="card">\n        <h2>🛡️ Dual-Custody Voice Execution Leases</h2>\n        <p class="card-desc">\n          High-consequence actions require cryptographic SHA-256 staging with 300s expiration and Alexa voice token verification.\n        </p>\n\n        <div class="actions-bar" style="margin-top: 0; margin-bottom: 14px;">\n          <button onclick="stageGovernedAction()">Stage Production Deploy</button>\n          <button class="btn-secondary" onclick="confirmVoiceAction()">Approve with Voice Token</button>\n          <button class="btn-danger" onclick="rejectAction()">Reject</button>\n        </div>\n\n        <div class="console-box" id="govConsole">\n          <div class="console-header">\n            <span>Active Execution Lease</span>\n            <span id="leaseTimer" class="tag tag-lease">IDLE</span>\n          </div>\n          <div id="govOutput">No active execution lease. Stage an action to initiate dual-custody approval.</div>\n        </div>\n\n        <div class="console-header" style="margin-top: 18px; margin-bottom: 6px;">\n          <span>Immutable Governance Vault Audit Log</span>\n          <span>SHA-256 Cryptographic Chain</span>\n        </div>\n        <div class="audit-list" id="auditVault">\n          <div class="audit-item">[GENESIS] Volcan Governance Engine active with least privilege.</div>\n        </div>\n      </div>\n\n      <!-- Card 3: Silent Tactile Braille Terminal -->\n      <div class="card" style="grid-column: 1 / -1;">\n        <h2>⠠⠃⠗⠁⠊⠇⠇⠑ Silent Tactile Braille Terminal (Refreshable Display Output)</h2>\n        <p class="card-desc">\n          For quiet hours, open offices, and deafblind software developers: Volcan converts AST diffs, code tokens, and governance leases directly into standard <strong>Unicode Braille Patterns (U+2800–U+28FF)</strong> for Refreshable Braille Displays (Focus 40, Orbit Reader, BRLTTY) with 100% silent operation.\n        </p>\n\n        <div class="actions-bar" style="margin-top: 0; margin-bottom: 14px;">\n          <button class="btn-purple" onclick="translateCurrentDiffToBraille()" title="Translate current AST diff to Braille stream">⠠⠙⠊⠋⠋ Translate Diff to Braille</button>\n          <button class="btn-secondary" onclick="translateCustomPromptToBraille()" title="Translate voice query to Braille">Translate Voice Input</button>\n          <button class="btn-secondary" onclick="copyBrailleStream()" title="Copy Unicode Braille to clipboard">Copy Braille Stream</button>\n        </div>\n\n        <div class="console-header">\n          <span>Tactile Braille Cell Stream (6-Dot Unicode Standard)</span>\n          <span class="tag tag-braille">UEB / Computer Braille</span>\n        </div>\n        <div class="braille-stream" id="brailleOutput">⠠⠧⠕⠇⠉⠁⠝⠀⠃⠗⠁⠊⠇⠇⠑⠀⠞⠑⠗⠍⠊⠝⠁⠇⠀⠗⠑⠁⠙⠽⠲⠀⠠⠉⠇⠊⠉⠅⠀⠁⠃⠕⠧⠑⠀⠞⠕⠀⠞⠗⠁⠝⠎⠇⠁⠞⠑⠀⠁⠝⠽⠀⠉⠕⠙⠑⠀⠕⠗⠀⠙⠊⠋⠋⠲</div>\n      </div>\n\n      <!-- Card 4: Amazon Multi-Device Ecosystem Companions -->\n      <div class="card" style="grid-column: 1 / -1; margin-top: 6px;">\n        <h2>🌐 Amazon Ecosystem Companions (Cross-Device Voice Integration)</h2>\n        <p class="card-desc">\n          Volcan\'s central Alexa+ voice forge coordinates ambient companion devices across your developer workspace.\n        </p>\n\n        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 14px; margin-top: 12px;">\n          <!-- Bee Companion -->\n          <div style="background: rgba(15, 23, 42, 0.8); border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; padding: 14px;">\n            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">\n              <span style="font-weight: 700; color: #93c5fd;">🐝 Bee Wearable</span>\n              <span class="tag tag-pass">Ambient Voice</span>\n            </div>\n            <p style="font-size: 0.82rem; color: #94a3b8; margin-bottom: 10px;">\n              Captures spontaneous spoken design decisions when away from the keyboard and attaches them as typed PR annotations.\n            </p>\n            <button class="btn-secondary" style="width: 100%; font-size: 0.82rem;" onclick="simulateBeeAnnotation()" title="Simulate Bee ambient note capture">Ingest Spoken Note</button>\n          </div>\n\n          <!-- Fire TV Companion -->\n          <div style="background: rgba(15, 23, 42, 0.8); border: 1px solid rgba(245, 158, 11, 0.3); border-radius: 8px; padding: 14px;">\n            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">\n              <span style="font-weight: 700; color: #fcd34d;">📺 Fire TV 10-Foot</span>\n              <span class="tag tag-lease">Wallboard</span>\n            </div>\n            <p style="font-size: 0.82rem; color: #94a3b8; margin-bottom: 10px;">\n              Broadcasts high-contrast accessible visual telemetry, waveform frequencies, and lease countdowns to ambient team screens.\n            </p>\n            <button class="btn-secondary" style="width: 100%; font-size: 0.82rem;" onclick="broadcastFireTvWallboard()" title="Broadcast telemetry to Fire TV">Sync Wallboard Frame</button>\n          </div>\n\n          <!-- Ring Companion -->\n          <div style="background: rgba(15, 23, 42, 0.8); border: 1px solid rgba(16, 185, 129, 0.3); border-radius: 8px; padding: 14px;">\n            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">\n              <span style="font-weight: 700; color: #6ee7b7;">🔔 Ring Sanctuary</span>\n              <span class="tag tag-pass">Focus Shield</span>\n            </div>\n            <p style="font-size: 0.82rem; color: #94a3b8; margin-bottom: 10px;">\n              Suppresses abrasive chimes during dual-custody release leases and chimes gentle 440Hz acoustic earcons on door arrival.\n            </p>\n            <button class="btn-secondary" style="width: 100%; font-size: 0.82rem;" onclick="testRingFocusPresence()" title="Test Ring focus presence trigger">Trigger Presence Event</button>\n          </div>\n        </div>\n\n        <div class="console-box" style="margin-top: 14px;" id="ecosystemConsole">\n          <div class="console-header">\n            <span>Ecosystem Companion Event Feed</span>\n            <span class="tag tag-pass">SYNCHRONIZED</span>\n          </div>\n          <div id="ecosystemOutput">Ready. Click any companion trigger above to simulate multi-device ecosystem coordination.</div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <script>\n    const PRESETS = {\n      1: `diff --git a/src/auth/service.py b/src/auth/service.py\nindex a1b2c3d..e5f6a7b 100644\n--- a/src/auth/service.py\n+++ b/src/auth/service.py\n@@ -10,4 +10,6 @@ class AuthService:\n     def authenticate(self, token: str) -> bool:\n-        return token == "hardcoded_secret"\n+        # Replace hardcoded secret with KMS key validation\n+        kms_key = os.environ.get("KMS_KEY_ID")\n+        return verify_kms_token(token, kms_key)`,\n      2: `diff --git a/src/routes/api.py b/src/routes/api.py\n--- a/src/routes/api.py\n+++ b/src/routes/api.py\n@@ -15,2 +15,4 @@\n+@router.get("/v1/health")\n+def health():\n+    return {"status": "healthy"}`,\n      3: `diff --git a/src/utils/parser.py b/src/utils/parser.py\n--- a/src/utils/parser.py\n+++ b/src/utils/parser.py\n@@ -4,3 +4,4 @@\n-    return data.strip()\n+    if not data: return ""\n+    return data.strip()`\n    };\n\n    const BRAILLE_MAP = {\n      \' \': \'\\u2800\', \'a\': \'\\u2801\', \'b\': \'\\u2803\', \'c\': \'\\u2809\', \'d\': \'\\u2819\',\n      \'e\': \'\\u2811\', \'f\': \'\\u280b\', \'g\': \'\\u281b\', \'h\': \'\\u2813\', \'i\': \'\\u280a\',\n      \'j\': \'\\u281a\', \'k\': \'\\u2805\', \'l\': \'\\u2807\', \'m\': \'\\u280d\', \'n\': \'\\u281d\',\n      \'o\': \'\\u2815\', \'p\': \'\\u280f\', \'q\': \'\\u281f\', \'r\': \'\\u2817\', \'s\': \'\\u280e\',\n      \'t\': \'\\u281e\', \'u\': \'\\u2825\', \'v\': \'\\u2827\', \'w\': \'\\u283a\', \'x\': \'\\u282d\',\n      \'y\': \'\\u283d\', \'z\': \'\\u2835\', \'1\': \'\\u2801\', \'2\': \'\\u2803\', \'3\': \'\\u2809\',\n      \'4\': \'\\u2819\', \'5\': \'\\u2811\', \'6\': \'\\u280b\', \'7\': \'\\u281b\', \'8\': \'\\u2813\',\n      \'9\': \'\\u280a\', \'0\': \'\\u281a\', \',\': \'\\u2802\', \';\': \'\\u2806\', \':\': \'\\u2812\',\n      \'.\': \'\\u2832\', \'!\': \'\\u2816\', \'?\': \'\\u2826\', \'(\': \'\\u2836\', \')\': \'\\u2836\',\n      \'-\': \'\\u2824\', \'+\': \'\\u282c\', \'=\': \'\\u2836\', \'/\': \'\\u280c\', \'\\\\\': \'\\u2821\',\n      \'*\': \'\\u2814\', \'#\': \'\\u283c\', \'@\': \'\\u2804\', \'_\': \'\\u2820\', \'{\': \'\\u2838\',\n      \'}\': \'\\u281c\', \'[\': \'\\u282a\', \']\': \'\\u283a\', \'<\': \'\\u2818\', \'>\': \'\\u2810\',\n      \'"\': \'\\u2810\', "\'": \'\\u2804\'\n    };\n\n    function jsTextToBraille(text) {\n      let res = \'\';\n      let inNum = false;\n      for (let ch of text) {\n        if (/\\d/.test(ch)) {\n          if (!inNum) { res += \'\\u283c\'; inNum = true; }\n          res += BRAILLE_MAP[ch] || \'\\u2800\';\n        } else {\n          inNum = false;\n          if (/[A-Z]/.test(ch)) {\n            res += \'\\u2820\' + (BRAILLE_MAP[ch.toLowerCase()] || \'\\u2800\');\n          } else if (BRAILLE_MAP[ch]) {\n            res += BRAILLE_MAP[ch];\n          } else if (ch === \'\\n\') {\n            res += \'\\n\';\n          } else {\n            res += \'\\u2800\';\n          }\n        }\n      }\n      return res;\n    }\n\n    function translateCurrentDiffToBraille() {\n      const diff = document.getElementById(\'diffInput\').value;\n      const braille = jsTextToBraille(diff);\n      document.getElementById(\'brailleOutput\').innerText = braille;\n      appendAudit(\'[BRAILLE] Diff rendered to 6-dot tactile stream for Refreshable Braille Display.\');\n    }\n\n    function translateCustomPromptToBraille() {\n      const text = document.getElementById(\'voiceCommandInput\').value;\n      const braille = jsTextToBraille(text);\n      document.getElementById(\'brailleOutput\').innerText = braille;\n      appendAudit(\'[BRAILLE] Voice prompt converted to silent Braille stream.\');\n    }\n\n    function copyBrailleStream() {\n      const text = document.getElementById(\'brailleOutput\').innerText;\n      navigator.clipboard.writeText(text).then(() => {\n        alert(\'Braille Unicode stream copied to clipboard!\');\n      });\n    }\n\n    function loadPreset(id) {\n      document.getElementById(\'diffInput\').value = PRESETS[id];\n      document.querySelectorAll(\'.chip\').forEach((c, idx) => {\n        c.classList.toggle(\'active\', idx === id - 1);\n      });\n    }\n    loadPreset(1);\n\n    function setVoicePrompt(text) {\n      document.getElementById(\'voiceCommandInput\').value = text;\n      executeVoiceCommand();\n    }\n\n    function speakText(text) {\n      if (\'speechSynthesis\' in window) {\n        window.speechSynthesis.cancel();\n        const utterance = new SpeechSynthesisUtterance(text);\n        utterance.rate = 1.05;\n        utterance.pitch = 1.0;\n        window.speechSynthesis.speak(utterance);\n      }\n    }\n\n    // Web Audio API pure synthesizer\n    let audioCtx = null;\n    function getAudioContext() {\n      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n      return audioCtx;\n    }\n\n    function playPureEarcon(type) {\n      const ctx = getAudioContext();\n      const osc = ctx.createOscillator();\n      const gain = ctx.createGain();\n      osc.connect(gain);\n      gain.connect(ctx.destination);\n\n      drawWaveformAnimation();\n\n      if (type === \'DIFF_READY\') {\n        osc.type = \'sine\';\n        osc.frequency.setValueAtTime(440, ctx.currentTime);\n        osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.12);\n        gain.gain.setValueAtTime(0.3, ctx.currentTime);\n        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15);\n        osc.start();\n        osc.stop(ctx.currentTime + 0.15);\n      } else if (type === \'ALERT\') {\n        osc.type = \'triangle\';\n        osc.frequency.setValueAtTime(320, ctx.currentTime);\n        osc.frequency.setValueAtTime(640, ctx.currentTime + 0.08);\n        gain.gain.setValueAtTime(0.4, ctx.currentTime);\n        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.2);\n        osc.start();\n        osc.stop(ctx.currentTime + 0.2);\n      } else if (type === \'CONFIRM\') {\n        osc.type = \'sine\';\n        osc.frequency.setValueAtTime(523.25, ctx.currentTime);\n        osc.frequency.setValueAtTime(659.25, ctx.currentTime + 0.08);\n        osc.frequency.setValueAtTime(783.99, ctx.currentTime + 0.16);\n        gain.gain.setValueAtTime(0.3, ctx.currentTime);\n        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.25);\n        osc.start();\n        osc.stop(ctx.currentTime + 0.25);\n      }\n    }\n\n    function drawWaveformAnimation() {\n      const canvas = document.getElementById(\'audioVisualizer\');\n      const ctx = canvas.getContext(\'2d\');\n      let start = null;\n      function step(timestamp) {\n        if (!start) start = timestamp;\n        let progress = (timestamp - start) / 350;\n        ctx.clearRect(0, 0, canvas.width, canvas.height);\n        ctx.strokeStyle = \'#38bdf8\';\n        ctx.lineWidth = 2;\n        ctx.beginPath();\n        for (let x = 0; x < canvas.width; x += 3) {\n          const y = canvas.height/2 + Math.sin(x*0.12 + progress*12) * Math.sin(progress*Math.PI) * 22;\n          if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);\n        }\n        ctx.stroke();\n        if (progress < 1) requestAnimationFrame(step);\n        else ctx.clearRect(0, 0, canvas.width, canvas.height);\n      }\n      requestAnimationFrame(step);\n    }\n\n    let stagedAction = null;\n    let timerInterval = null;\n\n    function synthesizeDiff(level) {\n      const diff = document.getElementById(\'diffInput\').value;\n      const hasSecurity = diff.includes(\'KMS_KEY_ID\') || diff.includes(\'secret\');\n      \n      let spoken = \'\';\n      let html = \'<strong>Spoken Digest:</strong> \';\n      if (level === 0) {\n        spoken = "One file modified with two additions. " + (hasSecurity ? "Security alert: Key Management Service token validation updated." : "Standard logic update.");\n        html += \'"\' + spoken + \'"\';\n      } else {\n        spoken = "Detailed abstract syntax tree breakdown: service.py updated authenticate method with environment KMS key lookup.";\n        html += \'"\' + spoken + \'"\';\n      }\n      html += \'<br><br><span class="tag tag-succ">1 File Changed</span> <span class="tag tag-succ">+2 / -1 Lines</span>\';\n      if (hasSecurity) {\n        html += \' <span class="tag tag-sec">Security Flag: KMS Token Audit</span>\';\n        playPureEarcon(\'ALERT\');\n      } else {\n        playPureEarcon(\'DIFF_READY\');\n      }\n      document.getElementById(\'diffOutput\').innerHTML = html;\n      speakText(spoken);\n    }\n\n    function executeVoiceCommand() {\n      const cmd = document.getElementById(\'voiceCommandInput\').value.toLowerCase();\n      if (cmd.includes(\'diff\') || cmd.includes(\'summarize\')) {\n        synthesizeDiff(0);\n      } else if (cmd.includes(\'stage\') || cmd.includes(\'deploy\')) {\n        stageGovernedAction();\n      } else if (cmd.includes(\'approve\') || cmd.includes(\'confirm\') || cmd.includes(\'token\')) {\n        confirmVoiceAction();\n      } else {\n        speakText("Command received by Volcan FastMCP server.");\n      }\n    }\n\n    function stageGovernedAction() {\n      stagedAction = {\n        id: \'act_\' + Math.floor(Math.random()*90000 + 10000),\n        command: \'aws ecs update-service --cluster prod --service volcan-api\',\n        hash: \'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\',\n        expires: Date.now() + 300000\n      };\n      playPureEarcon(\'DIFF_READY\');\n      \n      let timeLeft = 300;\n      clearInterval(timerInterval);\n      timerInterval = setInterval(() => {\n        timeLeft--;\n        if (timeLeft <= 0) {\n          clearInterval(timerInterval);\n          document.getElementById(\'leaseTimer\').innerText = \'LEASE EXPIRED\';\n          document.getElementById(\'govOutput\').innerText = \'Execution lease expired. Staged action discarded.\';\n          stagedAction = null;\n        } else {\n          document.getElementById(\'leaseTimer\').innerText = \'LEASE ACTIVE (\' + timeLeft + \'s)\';\n        }\n      }, 1000);\n\n      document.getElementById(\'govOutput\').innerHTML = \n        \'<strong>Staged Action:</strong> \' + stagedAction.id + \'<br>\' +\n        \'<strong>Target:</strong> <code>\' + stagedAction.command + \'</code><br>\' +\n        \'<strong>SHA-256 Hash Lock:</strong> <code>\' + stagedAction.hash.substring(0, 16) + \'...</code><br>\' +\n        \'<span style="color:#f97316;">Voice Confirmation Required: "Alexa, approve action \' + stagedAction.id + \'"</span>\';\n      \n      appendAudit(\'[STAGED] Action \' + stagedAction.id + \' locked under 300s lease (\' + stagedAction.hash.substring(0, 8) + \')\');\n      speakText("Action " + stagedAction.id + " staged for production. Dual custody lease active for 300 seconds. Awaiting voice confirmation.");\n    }\n\n    function confirmVoiceAction() {\n      if (!stagedAction) {\n        alert(\'Please stage an action first.\');\n        return;\n      }\n      clearInterval(timerInterval);\n      document.getElementById(\'leaseTimer\').innerText = \'COMMITTED\';\n      document.getElementById(\'govOutput\').innerHTML = \n        \'<span class="tag tag-succ">COMMITTED</span> <strong>Action \' + stagedAction.id + \' successfully deployed!</strong><br>\' +\n        \'Verified by Alexa Voice Token: <code>VOICE_TOKEN_ALEXA_AUTH_2026</code>\';\n      playPureEarcon(\'CONFIRM\');\n      appendAudit(\'[COMMITTED] Action \' + stagedAction.id + \' approved by voice token. Production updated.\');\n      speakText("Voice token verified. Production deployment executed successfully.");\n      stagedAction = null;\n    }\n\n    function rejectAction() {\n      if (!stagedAction) return;\n      clearInterval(timerInterval);\n      document.getElementById(\'leaseTimer\').innerText = \'REJECTED\';\n      document.getElementById(\'govOutput\').innerHTML = \'<span class="tag tag-sec">REJECTED</span> Action discarded by operator.\';\n      appendAudit(\'[REJECTED] Action \' + stagedAction.id + \' aborted.\');\n      speakText("Action aborted by operator.");\n      stagedAction = null;\n    }\n\n    function appendAudit(msg) {\n      const time = new Date().toISOString().substring(11, 19);\n      const div = document.createElement(\'div\');\n      div.className = \'audit-item\';\n      div.innerText = \'[\' + time + \'] \' + msg;\n      document.getElementById(\'auditVault\').prepend(div);\n    }\n\n    function simulateBeeAnnotation() {\n      const note = "Spoken note from developer Bee Wearable: Remember to verify KMS rotation in staging.";\n      document.getElementById(\'ecosystemOutput\').innerHTML = \n        \'<span class="tag tag-pass">🐝 BEE WEARABLE EVENT</span><br>\' +\n        \'<strong>Captured Transcript:</strong> "\' + note + \'"<br>\' +\n        \'<strong>Status:</strong> Attached to active PR review context. Harmonic earcon queued.\';\n      playPureEarcon(\'PASS\');\n      speakText("Ambient voice note captured from Bee Wearable. Attached to PR context.");\n      appendAudit(\'[BEE-COMPANION] Ambient spoken decision ingested from wearable device.\');\n    }\n\n    function broadcastFireTvWallboard() {\n      const rating = "ELITE";\n      document.getElementById(\'ecosystemOutput\').innerHTML = \n        \'<span class="tag tag-lease">📺 FIRE TV 10-FOOT BROADCAST</span><br>\' +\n        \'<strong>Telemetry Frame:</strong> Active lease TTL & AST security waveform synced.<br>\' +\n        \'<strong>DORA Velocity:</strong> \' + rating + \' | High-contrast Leanback theme active.\';\n      playPureEarcon(\'CONFIRM\');\n      speakText("Fire TV 10-foot ambient wallboard synchronized.");\n      appendAudit(\'[FIRETV-COMPANION] 10-foot high contrast frame broadcast to team display.\');\n    }\n\n    function testRingFocusPresence() {\n      const zone = "Front Door";\n      document.getElementById(\'ecosystemOutput\').innerHTML = \n        \'<span class="tag tag-pass">🔔 RING SANCTUARY SHIELD</span><br>\' +\n        \'<strong>Motion Detected:</strong> \' + zone + \'<br>\' +\n        \'<strong>Policy:</strong> Dual-custody focus active. Suppressed loud chime & played gentle 440Hz acoustic earcon.\';\n      playPureEarcon(\'PASS\');\n      speakText("Gentle notice: Motion at front door. Focus sanctuary active.");\n      appendAudit(\'[RING-COMPANION] Sanctuary focus shield suppressed loud chime; gentle earcon played.\');\n    }\n  </script>\n</body>\n</html>\n'
